-- rice-retro — GENERATED by theme-palette. Edit themes/retro/seed.sh instead.
-- IntelliJ-New-UI-flavored mapping over the retro palette.
vim.cmd.highlight("clear")
vim.g.colors_name = "rice-retro"
vim.o.termguicolors = true

local c = {
  bg = "#231f15", bg_dark = "#1b170e", bg_hl = "#383122",
  fg = "#d6d1c1", muted = "#989281", accent = "#f68000", alt = "#be9f00",
  red = "#ff7969", green = "#8abb24", yellow = "#f7be00",
  blue = "#ac93ff", magenta = "#f772b5", cyan = "#00d7a2",
  kw = "#fc9c6a", fn = "#a8b0fe", str = "#97b869",
  num = "#58cfb8", typ = "#e1bf7e", const = "#e19dd8",
  prop = "#e6bfaa", comment = "#817a66", op = "#b2ad9e",
  special = "#be9f00",
  border_a = "#955d03", border_i = "#2e291c",
  black = "#473f2f", bblack = "#655d4c",
}

local hl = function(g, o) vim.api.nvim_set_hl(0, g, o) end

-- editor chrome: low-contrast separators, quiet gutters, accent only on focus
hl("Normal", { fg = c.fg, bg = c.bg })
hl("NormalFloat", { fg = c.fg, bg = c.bg_dark })
